const presets={
 beginner:{w:9,h:9,m:10},
 intermediate:{w:16,h:16,m:40},
 expert:{w:30,h:16,m:99},
 custom:{w:30,h:20,m:100}
};
let state={...presets.custom}, started=Date.now();
const board=document.getElementById('board');
const mineCount=document.getElementById('mineCount');
const timeCount=document.getElementById('timeCount');
const smile=document.querySelector('#faceBtn img');
function makeBoard(){
  board.innerHTML='';
  board.style.gridTemplateColumns=`repeat(${state.w},23px)`;
  board.className='board '+(state.w>=30?'expert':'');
  mineCount.textContent=String(state.m).padStart(3,'0');
  for(let i=0;i<state.w*state.h;i++){
    const c=document.createElement('div');
    c.className='cell btn';
    c.dataset.index=i;
    c.addEventListener('click',()=>openCell(c));
    c.addEventListener('contextmenu',e=>{e.preventDefault();c.classList.toggle('flag');c.textContent=c.classList.contains('flag')?'⚑':''});
    board.appendChild(c);
  }
}
function openCell(c){
  if(c.classList.contains('flag'))return;
  const i=+c.dataset.index, x=i%state.w,y=Math.floor(i/state.w);
  if((i*17+x*3+y*7)%29===0){
    c.classList.add('open','mine');c.textContent='✹';
    smile.src='__PLACEHOLDER_ASSETS_BASE_DIR__/021.svg';
  }else{
    let n=(i*13+x+y)%6;
    c.classList.add('open');
    if(n){c.textContent=n;c.classList.add('n'+Math.min(n,4))}
  }
}
function selectMode(mode){
  document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.mode===mode));
  if(mode==='custom'){
    document.getElementById('customForm').classList.add('show');
    state={w:+widthInput.value||30,h:+heightInput.value||20,m:+minesInput.value||100};
  }else{
    document.getElementById('customForm').classList.remove('show');
    state={...presets[mode]};
  }
  makeBoard();
}
document.querySelectorAll('.tab').forEach(t=>t.addEventListener('click',()=>selectMode(t.dataset.mode)));
updateBtn.addEventListener('click',()=>{
 state={w:Math.max(5,+widthInput.value||30),h:Math.max(5,+heightInput.value||20),m:+minesInput.value||100};
 makeBoard();
});
faceBtn.addEventListener('click',()=>{smile.src='__PLACEHOLDER_ASSETS_BASE_DIR__/022.svg';started=Date.now();makeBoard()});
setInterval(()=>{timeCount.textContent=String(Math.floor((Date.now()-started)/1000)%1000).padStart(3,'0')},1000);
makeBoard();
